156	export function submitSegmentAudio(segment_id: string, source_text?: string) {
157	  const segment = getSegment(segment_id);
158	  if (!segment) throw new Error(`Segment not found: ${segment_id}`);
159	
160	  const text = (source_text ?? segment.narration_cn ?? segment.narration ?? "").trim();
161	  if (!text) throw new Error("Audio source text is empty");
162	
163	  const existing = listAudioTasks(segment_id);
164	  const latest = existing.at(-1);
165	  if (latest?.task_status === "processing" || latest?.task_status === "pending" || latest?.task_status === "completed") {
166	    return {
167	      task: latest,
168	      created: false,
169	      message: `audio for ${segment_id} is already ${latest.task_status}`
170	    };
171	  }
172	
173	  if (latest?.task_status === "failed") {
174	    return {
175	      task: latest,
176	      created: false,
177	      message: `audio for ${segment_id} is failed; retry explicitly`
178	    };
179	  }
180	
181	  const provider_task_id = submitMockAudioTask(segment_id, text);
182	  const task = addAudioTask({
183	    audio_task_id: nextAudioTaskId(segment_id, existing.length + 1),
184	    segment_id,
185	    provider_task_id,
186	    task_status: "processing",
187	    source_text: text,
188	    result_url: null,
189	    error_message: null,
190	    created_at: now(),
191	    updated_at: now()
192	  });
193	
194	  return {
195	    task,
196	    created: true,
197	    message: `audio for ${segment_id} submitted`
198	  };
199	}
200	
201	export function retrySegmentAudio(segment_id: string, source_text?: string) {
202	  const segment = getSegment(segment_id);
203	  if (!segment) throw new Error(`Segment not found: ${segment_id}`);
204	  const failed = [...listAudioTasks(segment_id)].reverse().find((task) => task.task_status === "failed");
205	  if (!failed) {
206	    return {
207	      task: listAudioTasks(segment_id).at(-1) ?? null,
208	      retried: false,
209	      message: `audio for ${segment_id} is not failed`
210	    };
211	  }
212	
213	  const text = (source_text ?? failed.source_text ?? segment.narration_cn ?? segment.narration ?? "").replace(/\s*\[FAIL\]/g, "").trim();
214	  if (!text) throw new Error("Audio source text is empty");
215	
216	  const provider_task_id = submitMockAudioTask(segment_id, text);
217	  const task = updateAudioTask(failed.audio_task_id, {
218	    provider_task_id,
219	    task_status: "processing",
220	    source_text: text,
221	    result_url: null,
222	    error_message: null
223	  });
224	
225	  return {
226	    task,
227	    retried: true,
228	    message: `audio for ${segment_id} retried`
229	  };
230	}
231	
232	export function retryMedia(media_id: string) {
233	  const media = getMediaCard(media_id);
234	  if (!media) throw new Error(`Media card not found: ${media_id}`);
235	  if (media.aggregate_status !== "failed") {
236	    return {
237	      media,
238	      tasks: listTasks(media_id),
239	      retried: false,
240	      message: `media ${media_id} is not failed`
241	    };
242	  }
243	
244	  const failed = listTasks(media_id).find((task) => task.task_status === "failed");
245	  if (!failed) throw new Error(`Failed task not found for media: ${media_id}`);
246	
247	  const patchedMedia: SegmentMedia = updateMediaCard(media_id, {
248	    prompt: media.prompt.replace(/\s*\[FAIL\]/g, "")
249	  });
250	  const provider_task_id = submitMockProviderTask(patchedMedia);
251	  updateTask(failed.media_task_id, {
252	    provider_task_id,
253	    task_status: "processing",
254	    result_url: null,
255	    error_message: null
256	  });
257	  const updated = recalculateMediaStatus(media_id);
258	
259	  return {
260	    media: updated,
261	    tasks: listTasks(media_id),
262	    retried: true,
263	    message: `media ${media_id} retried`
264	  };
265	}
