1	import { bulkSampleSchema } from "./schemas";
2	import type { BulkSample, ValidationIssue, ValidationReport } from "./types";
3	
4	function issue(issues: ValidationIssue[], code: string, message: string, path?: string) {
5	  issues.push({ code, message, path });
6	}
7	
8	function unique<T extends object, K extends keyof T & string>(items: T[], key: K, label: string, issues: ValidationIssue[]) {
9	  const seen = new Set<string>();
10	  for (const item of items) {
11	    const id = String(item[key]);
12	    if (seen.has(id)) issue(issues, "duplicate_id", `${label} id must be unique: ${id}`, `${label}.${key}`);
13	    seen.add(id);
14	  }
15	}
16	
17	function counts(input: unknown): ValidationReport["counts"] {
18	  const maybe = input as Partial<Record<keyof BulkSample, unknown>> | null;
19	  return {
20	    ideas: Array.isArray(maybe?.ideas) ? maybe.ideas.length : 0,
21	    scenes: Array.isArray(maybe?.scenes) ? maybe.scenes.length : 0,
22	    segments: Array.isArray(maybe?.segments) ? maybe.segments.length : 0,
23	    media_cards: Array.isArray(maybe?.media_cards) ? maybe.media_cards.length : 0,
24	    covers: Array.isArray(maybe?.covers) ? maybe.covers.length : 0
25	  };
26	}
27	
28	export function validateSample(input: unknown): ValidationReport {
29	  const parsed = bulkSampleSchema.safeParse(input);
30	  const baseCounts = counts(input);
31	  if (!parsed.success) {
32	    return {
33	      ok: false,
34	      counts: baseCounts,
35	      issues: parsed.error.issues.map((item) => ({
36	        code: "schema",
37	        message: item.message,
38	        path: item.path.join(".")
39	      }))
40	    };
41	  }
42	
43	  const data = parsed.data;
44	  const issues: ValidationIssue[] = [];
45	  unique(data.ideas, "idea_id", "idea", issues);
46	  unique(data.scenes, "scene_id", "scene", issues);
47	  unique(data.segments, "segment_id", "segment", issues);
48	  unique(data.media_cards, "media_id", "media_card", issues);
49	  unique(data.covers, "cover_id", "cover", issues);
50	
51	  const ideaIds = new Set(data.ideas.map((item) => item.idea_id));
52	  const sceneIds = new Set(data.scenes.map((item) => item.scene_id));
53	  const segmentIds = new Set(data.segments.map((item) => item.segment_id));
54	
55	  for (const scene of data.scenes) {
56	    if (!ideaIds.has(scene.idea_id)) issue(issues, "missing_reference", `scene ${scene.scene_id} references missing idea`, "scene.idea_id");
57	  }
58	
59	  for (const segment of data.segments) {
60	    if (!sceneIds.has(segment.scene_id)) {
61	      issue(issues, "missing_reference", `segment ${segment.segment_id} references missing scene`, "segment.scene_id");
62	    }
63	  }
64	
65	  for (const media of data.media_cards) {
66	    if (!segmentIds.has(media.segment_id)) {
67	      issue(issues, "missing_reference", `media ${media.media_id} references missing segment`, "media.segment_id");
68	    }
69	
70	    if (media.reference_images_json.length > 3) {
71	      issue(issues, "too_many_references", `media ${media.media_id} has more than 3 reference images`, "media.reference_images_json");
72	    }
73	
74	    if (media.media_type === "image") {
75	      if (media.provider !== "mock-image") issue(issues, "provider_mismatch", `image media ${media.media_id} must use mock-image`, "media.provider");
76	      if (media.generate_count < 1 || media.generate_count > 4) {
77	        issue(issues, "invalid_generate_count", `image media ${media.media_id} generate_count must be 1..4`, "media.generate_count");
78	      }
79	      if (media.duration !== null) issue(issues, "invalid_duration", `image media ${media.media_id} must not set duration`, "media.duration");
80	    }
81	
82	    if (media.media_type === "video") {
83	      if (media.provider !== "mock-video") issue(issues, "provider_mismatch", `video media ${media.media_id} must use mock-video`, "media.provider");
84	      if (media.generate_count !== 1) issue(issues, "invalid_generate_count", `video media ${media.media_id} generate_count must equal 1`, "media.generate_count");
85	      if (media.duration === null || media.duration < 4 || media.duration > 12) {
86	        issue(issues, "invalid_duration", `video media ${media.media_id} duration must be 4..12`, "media.duration");
87	      }
88	    }
89	  }
90	
91	  for (const cover of data.covers) {
92	    if (!ideaIds.has(cover.idea_id)) issue(issues, "missing_reference", `cover ${cover.cover_id} references missing idea`, "cover.idea_id");
93	  }
94	
95	  return {
96	    ok: issues.length === 0,
97	    counts: baseCounts,
98	    issues
99	  };
100	}
