1	import type { MediaType, SegmentMedia } from "./types";
2	
3	interface ProviderJob {
4	  entity_id: string;
5	  job_type: "media" | "audio";
6	  media_type: MediaType | null;
7	  poll_count: number;
8	  should_fail: boolean;
9	}
10	
11	const jobs = new Map<string, ProviderJob>();
12	let counter = 0;
13	
14	export function resetMockProvider() {
15	  jobs.clear();
16	  counter = 0;
17	}
18	
19	export function submitMockProviderTask(media: SegmentMedia) {
20	  counter += 1;
21	  const provider_task_id = `MOCK_JOB_${String(counter).padStart(3, "0")}`;
22	  jobs.set(provider_task_id, {
23	    entity_id: media.media_id,
24	    job_type: "media",
25	    media_type: media.media_type,
26	    poll_count: 0,
27	    should_fail: media.prompt.includes("[FAIL]")
28	  });
29	  return provider_task_id;
30	}
31	
32	export function submitMockAudioTask(segment_id: string, source_text: string) {
33	  counter += 1;
34	  const provider_task_id = `MOCK_AUDIO_${String(counter).padStart(3, "0")}`;
35	  jobs.set(provider_task_id, {
36	    entity_id: segment_id,
37	    job_type: "audio",
38	    media_type: null,
39	    poll_count: 0,
40	    should_fail: source_text.includes("[FAIL]")
41	  });
42	  return provider_task_id;
43	}
44	
45	export function pollMockProviderTask(provider_task_id: string) {
46	  const job = jobs.get(provider_task_id);
47	  if (!job) {
48	    return {
49	      task_status: "failed" as const,
50	      result_url: null,
51	      error_message: `Unknown mock provider task: ${provider_task_id}`
52	    };
53	  }
54	
55	  job.poll_count += 1;
56	  if (job.poll_count < 2) {
57	    return {
58	      task_status: "processing" as const,
59	      result_url: null,
60	      error_message: null
61	    };
62	  }
63	
64	  if (job.should_fail) {
65	    return {
66	      task_status: "failed" as const,
67	      result_url: null,
68	      error_message: "Mock provider failed because source text includes [FAIL]."
69	    };
70	  }
71	
72	  if (job.job_type === "audio") {
73	    return {
74	      task_status: "completed" as const,
75	      result_url: "/mock-assets/mock-audio.wav",
76	      error_message: null
77	    };
78	  }
79	
80	  const extension = job.media_type === "video" ? "mp4" : "png";
81	  return {
82	    task_status: "completed" as const,
83	    result_url: `/mock-assets/${job.entity_id}.${extension}`,
84	    error_message: null
85	  };
86	}
