18	}
19	
20	let state: MockState = createInitialState();
21	
22	function createInitialState(): MockState {
23	  return {
24	    settings: clone(initialSettings),
25	    ideas: clone(initialSample.ideas),
26	    scenes: clone(initialSample.scenes),
27	    segments: clone(initialSample.segments),
