27	function parseSrtTime(value: string) {
28	  const match = value.match(/^(\d{2}):(\d{2}):(\d{2}),(\d{3})$/);
29	  if (!match) return null;
30	  const [, hours, minutes, seconds, ms] = match;
31	  return Number(hours) * 3600 + Number(minutes) * 60 + Number(seconds) + Number(ms) / 1000;
32	}
33	
34	function parseSrt(text: string) {
35	  const blocks = text.trim().split(/\r?\n\r?\n+/).filter(Boolean);
36	  return blocks.flatMap((block) => {
37	    const lines = block.split(/\r?\n/);
38	    const timingIndex = lines.findIndex((line) => line.includes("-->"));
39	    if (timingIndex === -1) return [];
40	    const [startRaw, endRaw] = lines[timingIndex].split("-->").map((item) => item.trim());
41	    const start = parseSrtTime(startRaw);
42	    const end = parseSrtTime(endRaw);
43	    if (start === null || end === null) return [];
44	    return [{ start, end, text: lines.slice(timingIndex + 1).join("") }];
45	  });
46	}
