13	function ffprobeDuration(filePath: string) {
14	  const output = execFileSync(
15	    "ffprobe",
16	    ["-v", "error", "-show_entries", "format=duration", "-of", "default=noprint_wrappers=1:nokey=1", filePath],
17	    { encoding: "utf8" }
18	  ).trim();
19	  return Number(output);
20	}
