82	function buildSubtitleCues(items: StoryboardItem[]) {
83	  const cues: SubtitleCue[] = [];
84	  let cueIndex = 1;
85	
86	  for (const item of items) {
87	    const segmentStart = item.timeline_start_seconds ?? 0;
88	    const segmentDuration = item.audio_duration_seconds ?? item.duration_seconds;
89	    const chunks = splitNarration(item.narration_cn);
90	    const weights = chunks.map(textLength);
91	    const totalWeight = weights.reduce((total, value) => total + value, 0) || chunks.length;
92	    let localCursor = 0;
93	
94	    chunks.forEach((chunk, chunkIndex) => {
95	      const isLast = chunkIndex === chunks.length - 1;
96	      const duration = isLast ? segmentDuration - localCursor : segmentDuration * (weights[chunkIndex] / totalWeight);
97	      const start = segmentStart + localCursor;
98	      const end = segmentStart + Math.min(segmentDuration, localCursor + duration);
99	      if (end > start) {
100	        cues.push({
101	          index: cueIndex,
102	          order: item.order,
103	          start_seconds: Number(start.toFixed(3)),
104	          end_seconds: Number(end.toFixed(3)),
105	          text: chunk
106	        });
107	        cueIndex += 1;
108	      }
109	      localCursor += duration;
110	    });
111	  }
112	
113	  return cues;
114	}
