116	function writeSrt(filePath: string, cues: SubtitleCue[]) {
117	  const lines = cues.flatMap((cue) => [
118	    String(cue.index),
119	    `${formatSrtTime(cue.start_seconds)} --> ${formatSrtTime(cue.end_seconds)}`,
120	    wrapSubtitleText(cue.text),
121	    ""
122	  ]);
123	  fs.writeFileSync(filePath, `${lines.join("\n").trimEnd()}\n`, "utf8");
124	}
