126	function findSubtitleFont() {
127	  try {
128	    const fonts = execFileSync("magick", ["-list", "font"], { encoding: "utf8" });
129	    const fontNames = ["PingFang-SC-Semibold", "Hiragino-Sans-GB-W6", "Heiti-SC-Medium"];
130	    const fontName = fontNames.find((candidate) => fonts.includes(`Font: ${candidate}`));
131	    if (fontName) return fontName;
132	  } catch {
133	    // Fall back to system font files below.
134	  }
135	  const candidates = [
136	    "/System/Library/Fonts/Hiragino Sans GB.ttc",
137	    "/System/Library/Fonts/STHeiti Medium.ttc",
138	    "/System/Library/Fonts/STHeiti Light.ttc",
139	    "/System/Library/Fonts/Supplemental/Arial Unicode.ttf"
140	  ];
141	  return candidates.find((candidate) => fs.existsSync(candidate));
142	}
