126	      fs.copyFileSync(tempPath, outputPath);
127	    }
128	    return ffprobeDuration(outputPath);
129	  } finally {
130	    if (fs.existsSync(tempPath)) fs.unlinkSync(tempPath);
131	  }
132	}
