134	function writeMockAudio(outputPath: string, durationSeconds: number, index: number) {
135	  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
136	  run("ffmpeg", [
137	    "-y",
138	    "-f",
139	    "lavfi",
140	    "-i",
141	    `sine=frequency=${360 + index * 70}:duration=${durationSeconds}:sample_rate=44100`,
142	    "-af",
143	    "volume=0.018",
144	    "-c:a",
145	    "libmp3lame",
146	    "-b:a",
147	    "128k",
148	    outputPath
149	  ]);
150	  return ffprobeDuration(outputPath);
151	}
