153	function updateStoryboardTimeline(storyboard: StoryboardFile, durations: Map<number, number>) {
154	  let cursor = 0;
155	  const nextItems = storyboard.items.map((item) => {
156	    const duration = Number((durations.get(item.order) ?? item.duration_seconds).toFixed(2));
157	    const updated = {
158	      ...item,
159	      audio_manifest_path: ensureMp3Path(item.audio_manifest_path),
160	      duration_seconds: duration,
161	      audio_duration_seconds: duration,
162	      timeline_start_seconds: Number(cursor.toFixed(2))
163	    };
164	    cursor += duration;
165	    return updated;
166	  });
167	  return {
168	    ...storyboard,
169	    total_duration_seconds: Number(cursor.toFixed(2)),
170	    items: nextItems
171	  };
172	}
