174	async function main() {
175	  const loadedEnvFiles = envCandidates.filter((candidate) => loadEnvFile(candidate));
176	  const storyboard = readJson<StoryboardFile>(videoRunFiles.storyboard);
177	  const manifestPath = path.join(process.cwd(), videoRunFiles.realAudioManifest);
178	  const maxRetries = numberFromEnv("REAL_AUDIO_MAX_RETRIES", 1, 30);
179	  const outputFormat = process.env.ELEVENLABS_OUTPUT_FORMAT?.trim() || "mp3_44100_128";
180	  const audioResults: Array<Record<string, unknown>> = [];
181	  const attempts: Array<Record<string, unknown>> = [];
182	  const durations = new Map<number, number>();
183	
184	  for (const [index, item] of storyboard.items.entries()) {
185	    const outputPath = path.join(process.cwd(), ensureMp3Path(item.audio_manifest_path));
186	    const previousText = storyboard.items[index - 1]?.narration_cn ?? null;
187	    const nextText = storyboard.items[index + 1]?.narration_cn ?? null;
188	    const targetDuration = item.duration_seconds || 10;
189	    let completed = false;
190	    let fallbackReason = "real_tts_not_attempted";
191	    let modelId = process.env.ELEVENLABS_MODEL_ID?.trim() || "eleven_multilingual_v2";
192	    let characterCount = item.narration_cn.length;
193	
194	    for (let attempt = 1; attempt <= maxRetries; attempt += 1) {
195	      try {
196	        const result = await textToSpeech(item, previousText, nextText);
197	        modelId = result.modelId;
198	        characterCount = result.characterCount;
199	        const duration = writeRealAudio(result.audioBuffer, outputPath, targetDuration);
200	        durations.set(item.order, duration);
201	        audioResults.push({
202	          order: item.order,
203	          title: item.title,
204	          status: "real_tts_completed" satisfies AudioStatus,
205	          path: toProjectPath(outputPath),
206	          duration_seconds: Number(duration.toFixed(2)),
207	          source_text_chars: item.narration_cn.length,
208	          character_count: characterCount,
209	          provider: "elevenlabs",
210	          model: modelId,
211	          fallback: false,
212	          attempts: attempt
213	        });
214	        attempts.push({ order: item.order, phase: "submit", attempt, ok: true, provider: "elevenlabs", model: modelId });
215	        completed = true;
216	        break;
217	      } catch (error) {
218	        fallbackReason = sanitizeText(error instanceof Error ? error.message : String(error));
219	        attempts.push({ order: item.order, phase: "submit", attempt, ok: false, error: fallbackReason });
220	      }
221	    }
222	
223	    if (!completed) {
224	      const duration = writeMockAudio(outputPath, targetDuration, index);
225	      durations.set(item.order, duration);
226	      audioResults.push({
227	        order: item.order,
228	        title: item.title,
229	        status: "mock_fallback" satisfies AudioStatus,
230	        path: toProjectPath(outputPath),
231	        duration_seconds: Number(duration.toFixed(2)),
232	        source_text_chars: item.narration_cn.length,
233	        character_count: characterCount,
234	        provider: "mock-audio",
235	        model: "ffmpeg-sine-fallback",
236	        fallback: true,
237	        fallback_reason: fallbackReason,
238	        attempts: maxRetries
239	      });
240	      attempts.push({ order: item.order, phase: "fallback", ok: true, provider: "mock-audio", reason: fallbackReason });
241	    }
242	  }
243	
244	  const updatedStoryboard = updateStoryboardTimeline(storyboard, durations);
245	  writeJson(path.join(process.cwd(), videoRunFiles.storyboard), updatedStoryboard);
246	
247	  const realCount = audioResults.filter((item) => item.status === "real_tts_completed").length;
248	  const fallbackCount = audioResults.filter((item) => item.status === "mock_fallback").length;
249	  const ok = audioResults.every((item) => typeof item.path === "string" && fs.existsSync(path.join(process.cwd(), String(item.path))));
250	
251	  writeJson(manifestPath, {
252	    ok,
253	    provider: "elevenlabs",
254	    media_type: "audio",
255	    mode: fallbackCount === 0 ? "real_tts_completed" : "mock_fallback",
256	    model: process.env.ELEVENLABS_MODEL_ID?.trim() || "eleven_multilingual_v2",
257	    output_format: outputFormat,
258	    loaded_env_files: loadedEnvFiles.map((file) => path.basename(file)),
259	    retry_policy: {
260	      max_retries: maxRetries,
261	      hard_cap: 30,
262	      failure_does_not_block_main_flow: true
263	    },
264	    timeline: {
265	      aligned_to_audio_duration: true,
266	      total_duration_seconds: updatedStoryboard.total_duration_seconds,
267	      items: updatedStoryboard.items.map((item) => ({
268	        order: item.order,
269	        start_seconds: item.timeline_start_seconds,
270	        duration_seconds: item.duration_seconds,
271	        audio_path: item.audio_manifest_path
272	      }))
273	    },
274	    audio: audioResults,
275	    attempts
276	  });
277	
278	  console.log("real-audio:smoke completed");
279	  console.log("provider=elevenlabs");
280	  console.log(`mode=${fallbackCount === 0 ? "real_tts_completed" : "mock_fallback"}`);
281	  console.log(`real_tts_completed=${realCount}/${audioResults.length}`);
282	  console.log(`mock_fallback=${fallbackCount}/${audioResults.length}`);
283	}
284	
285	main().catch((error) => {
286	  const message = sanitizeText(error instanceof Error ? error.message : String(error));
287	  console.error(`real-audio:smoke failed before fallback: ${message}`);
288	  process.exit(1);
289	});
