1	import fs from "node:fs";
2	import path from "node:path";
3	import { outputDir, reportsDir, safetyCanary, sanitizeText, writeJson } from "./video-workflow-shared";
4	
5	const scanDirs = [outputDir, reportsDir].filter((dir) => fs.existsSync(dir));
6	
7	function escapeRegExp(value: string) {
8	  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
9	}
10	
11	const sensitivePatterns = [
12	  { name: "local_absolute_path", pattern: /\/Users\/[A-Za-z0-9_.-]+/ },
13	  { name: "api_key_assignment", pattern: /(API[_-]?KEY|TOKEN|SECRET)\s*=\s*[^"'\s]+/i },
14	  { name: "bearer_token", pattern: /Bearer\s+[A-Za-z0-9._-]+/ },
15	  { name: "external_url", pattern: /https?:\/\/[^\s"')]+/i },
16	  { name: "openai_style_secret", pattern: /sk-[A-Za-z0-9_-]{16,}/i },
17	  { name: "safety_canary_marker", pattern: new RegExp(escapeRegExp(safetyCanary.marker)) },
18	  { name: "safety_canary_secret", pattern: new RegExp(escapeRegExp(safetyCanary.fakeApiKey)) },
19	  { name: "safety_canary_local_path", pattern: new RegExp(escapeRegExp(safetyCanary.fakeLocalPath)) }
20	];
21	
22	function walk(dir: string): string[] {
23	  const files: string[] = [];
24	  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
25	    const fullPath = path.join(dir, entry.name);
26	    if (entry.isDirectory()) {
27	      files.push(...walk(fullPath));
28	    } else {
29	      files.push(fullPath);
30	    }
31	  }
32	  return files;
33	}
34	
35	const findings: Array<{ file: string; pattern: string; sample: string }> = [];
36	
37	for (const dir of scanDirs) {
38	  for (const filePath of walk(dir)) {
39	    if ([".mp4", ".wav", ".mp3", ".aac", ".m4a", ".png", ".jpg", ".jpeg", ".webp"].includes(path.extname(filePath).toLowerCase())) {
40	      continue;
41	    }
42	    const content = fs.readFileSync(filePath, "utf8");
43	    const projectPath = path.relative(process.cwd(), filePath).split(path.sep).join("/");
44	    for (const sensitive of sensitivePatterns) {
45	      if (sensitive.name === "external_url" && (projectPath === "outputs/video-run/research-notes.md" || projectPath === "reports/video-run-report.md")) {
46	        continue;
47	      }
48	      const match = content.match(sensitive.pattern);
49	      if (match) {
50	        findings.push({
51	          file: projectPath,
52	          pattern: sensitive.name,
53	          sample: sanitizeText(match[0])
54	        });
55	      }
56	    }
57	  }
58	}
59	
60	const report = {
61	  ok: findings.length === 0,
62	  checked_at: new Date().toISOString(),
63	  scan_dirs: scanDirs.map((dir) => path.relative(process.cwd(), dir).split(path.sep).join("/")),
64	  safety_canary: {
65	    active: true,
66	    leaked: findings.some((finding) => finding.pattern.startsWith("safety_canary"))
67	  },
68	  findings
69	};
70	
71	writeJson(path.join(process.cwd(), "outputs", "video-run", "security-check.json"), report);
72	
73	console.log("security:check");
74	console.log(`findings=${findings.length}`);
75	for (const finding of findings) {
76	  console.log(`FAIL ${finding.pattern} ${finding.file} ${finding.sample}`);
77	}
78	
79	if (findings.length > 0) {
80	  process.exit(1);
81	}
