75	async function copyTextToClipboard(text: string) {
76	  try {
77	    if (navigator.clipboard?.writeText) {
78	      await navigator.clipboard.writeText(text);
79	      return;
80	    }
81	  } catch {
82	    // Fall back to a temporary textarea below. This is useful in embedded browsers.
83	  }
84	
85	  const textarea = document.createElement("textarea");
86	  textarea.value = text;
87	  textarea.setAttribute("readonly", "true");
88	  textarea.style.position = "fixed";
89	  textarea.style.left = "-9999px";
90	  textarea.style.top = "0";
91	  document.body.appendChild(textarea);
92	  textarea.focus();
93	  textarea.select();
94	  const copied = document.execCommand("copy");
95	  document.body.removeChild(textarea);
96	
97	  if (!copied) {
98	    throw new Error("clipboard not supported");
99	  }
