14	function record(events: unknown[], action: string, value: unknown) {
15	  events.push({
16	    action,
17	    value
18	  });
19	}
20	
21	function pollTwice(events: unknown[], label: string) {
22	  const first = pollRunningTasks();
23	  const second = pollRunningTasks();
24	  record(events, `${label}:poll_1`, {
25	    updated_tasks: first.updated_tasks,
26	    media_statuses: first.tasks.map((task) => task.task_status),
27	    audio_statuses: first.audio_tasks.map((task) => task.task_status)
28	  });
29	  record(events, `${label}:poll_2`, {
30	    updated_tasks: second.updated_tasks,
31	    media_statuses: second.tasks.map((task) => task.task_status),
32	    audio_statuses: second.audio_tasks.map((task) => task.task_status)
33	  });
34	}
