1	import fs from "node:fs";
2	import path from "node:path";
3	import { readJson, outputDir, sanitizeText, toProjectPath, videoRunFiles, writeJson, type StoryboardFile } from "./video-workflow-shared";
4	
5	type TaskStatus = "pending" | "processing" | "completed" | "failed" | "cancelled";
6	type JsonRecord = Record<string, unknown>;
7	
8	const homeDir = process.env.HOME ?? "";
9	const configuredFallbacks = (process.env.REAL_MEDIA_ENV_FALLBACKS ?? "")
10	  .split(path.delimiter)
11	  .map((item) => item.trim())
12	  .filter(Boolean);
13	
14	const envCandidates = [
15	  path.resolve(process.cwd(), ".env.local"),
16	  process.env.REAL_MEDIA_ENV_FILE ? path.resolve(process.env.REAL_MEDIA_ENV_FILE) : null,
17	  ...configuredFallbacks.map((item) => path.resolve(item)),
18	  homeDir ? path.join(homeDir, "Desktop", "tt_idea", "ttvideo_workflow", ".env") : null,
19	  homeDir ? path.join(homeDir, "Desktop", "ship", "youtube_long", ".env") : null,
20	  homeDir ? path.join(homeDir, "Desktop", "ship", "oldmoney_main", ".env") : null
21	].filter(Boolean) as string[];
22	
23	function loadEnvFile(filePath: string) {
24	  if (!fs.existsSync(filePath)) return false;
25	  const lines = fs.readFileSync(filePath, "utf8").split(/\r?\n/);
26	  for (const line of lines) {
27	    const trimmed = line.trim();
28	    if (!trimmed || trimmed.startsWith("#")) continue;
29	    const eqIndex = trimmed.indexOf("=");
30	    if (eqIndex === -1) continue;
31	    const key = trimmed.slice(0, eqIndex).trim();
32	    const rawValue = trimmed.slice(eqIndex + 1).trim();
33	    const value = rawValue.replace(/^["']|["']$/g, "");
34	    if (key && process.env[key] === undefined) process.env[key] = value;
35	  }
36	  return true;
37	}
38	
39	function asRecord(value: unknown): JsonRecord | null {
40	  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : null;
41	}
42	
43	function asString(value: unknown): string | null {
44	  return typeof value === "string" && value.trim() ? value.trim() : null;
45	}
46	
47	function firstStringInArray(value: unknown): string | null {
48	  if (!Array.isArray(value)) return null;
49	  for (const item of value) {
50	    const text = asString(item);
51	    if (text) return text;
52	  }
53	  return null;
54	}
55	
56	function firstRecordInArray(value: unknown): JsonRecord | null {
57	  if (!Array.isArray(value)) return null;
58	  for (const item of value) {
59	    const record = asRecord(item);
60	    if (record) return record;
61	  }
62	  return null;
63	}
64	
65	function pickNestedRecord(data: JsonRecord): JsonRecord | null {
66	  return asRecord(data.data) ?? firstRecordInArray(data.data) ?? asRecord(data.result) ?? firstRecordInArray(data.result) ?? null;
67	}
68	
69	function extractTaskId(data: JsonRecord): string | null {
70	  const direct = asString(data.task_id) ?? asString(data.id) ?? asString(data.taskId);
71	  if (direct) return direct;
72	  const nested = pickNestedRecord(data);
73	  return nested ? asString(nested.task_id) ?? asString(nested.id) ?? asString(nested.taskId) : null;
74	}
75	
76	function extractStatus(data: JsonRecord): TaskStatus {
77	  const nested = pickNestedRecord(data);
78	  const raw = asString(data.task_status) ?? asString(data.status) ?? asString(nested?.task_status) ?? asString(nested?.status);
79	  const normalized = raw?.toLowerCase();
80	  if (normalized === "pending" || normalized === "queued" || normalized === "submitted") return "pending";
81	  if (normalized === "completed" || normalized === "succeeded" || normalized === "success" || normalized === "done") return "completed";
82	  if (normalized === "failed" || normalized === "error") return "failed";
83	  if (normalized === "cancelled" || normalized === "canceled") return "cancelled";
84	  return "processing";
85	}
86	
87	function extractResultUrl(data: JsonRecord): string | null {
88	  const nested = pickNestedRecord(data);
89	  const candidates = [data, nested].filter(Boolean) as JsonRecord[];
90	  for (const record of candidates) {
91	    const direct =
92	      asString(record.url) ??
93	      asString(record.image_url) ??
94	      asString(record.download_url) ??
95	      firstStringInArray(record.urls) ??
96	      firstStringInArray(record.image_urls);
97	    if (direct) return direct;
98	
99	    const output = asRecord(record.output);
100	    if (output) {
101	      const nestedUrl =
102	        asString(output.url) ??
103	        asString(output.image_url) ??
104	        firstStringInArray(output.urls) ??
105	        firstStringInArray(output.image_urls);
106	      if (nestedUrl) return nestedUrl;
107	    }
108	
109	    const result = asRecord(record.result);
110	    const firstImage = firstRecordInArray(result?.images);
111	    if (firstImage) {
112	      const imageUrl =
113	        asString(firstImage.url) ??
114	        firstStringInArray(firstImage.url) ??
115	        asString(firstImage.image_url) ??
116	        firstStringInArray(firstImage.image_url);
117	      if (imageUrl) return imageUrl;
118	    }
119	  }
120	  return null;
121	}
122	
123	function publicError(data: JsonRecord): string | null {
124	  const nested = pickNestedRecord(data);
125	  return asString(data.message) ?? asString(data.error) ?? asString(nested?.message) ?? asString(nested?.error);
126	}
127	
128	async function parseResponseJson(response: Response): Promise<JsonRecord> {
129	  return (await response.json().catch(() => ({}))) as JsonRecord;
130	}
131	
132	function requiredEnv(name: string) {
133	  const value = process.env[name]?.trim();
134	  if (!value) throw new Error(`${name} is not configured`);
135	  return value;
136	}
137	
138	function numberFromEnv(name: string, fallback: number, max: number) {
139	  const value = Number(process.env[name] ?? fallback);
140	  if (!Number.isFinite(value) || value <= 0) return fallback;
141	  return Math.min(Math.floor(value), max);
142	}
143	
144	function sleep(ms: number) {
145	  return new Promise((resolve) => setTimeout(resolve, ms));
146	}
147	
148	async function submitImage(submitUrl: string, apiKey: string, model: string, prompt: string) {
149	  const response = await fetch(submitUrl, {
150	    method: "POST",
151	    headers: {
152	      "Content-Type": "application/json",
153	      Authorization: `Bearer ${apiKey}`
154	    },
155	    body: JSON.stringify({
156	      model,
157	      prompt,
158	      image_urls: [],
159	      size: "16:9",
160	      resolution: "1K"
161	    })
162	  });
163	  const data = await parseResponseJson(response);
164	  const taskId = extractTaskId(data);
165	  if (!response.ok || !taskId) {
166	    throw new Error(`submit_failed status=${response.status} message=${sanitizeText(publicError(data) ?? "unknown")}`);
167	  }
168	  return taskId;
169	}
170	
171	async function getStatus(baseUrl: string, statusBasePath: string, taskId: string, apiKey: string) {
172	  const statusUrl = new URL(`${statusBasePath}/${taskId}`, baseUrl).toString();
173	  const response = await fetch(statusUrl, {
174	    method: "GET",
175	    headers: {
176	      Authorization: `Bearer ${apiKey}`
177	    }
178	  });
179	  const data = await parseResponseJson(response);
180	  if (!response.ok) {
181	    throw new Error(`status_failed status=${response.status} message=${sanitizeText(publicError(data) ?? "unknown")}`);
182	  }
183	  return {
184	    task_status: extractStatus(data),
185	    result_url: extractResultUrl(data),
186	    error_message: sanitizeText(publicError(data) ?? "")
187	  };
188	}
189	
190	async function downloadImage(resultUrl: string, outputPath: string) {
191	  const response = await fetch(resultUrl);
192	  if (!response.ok) throw new Error(`download_failed status=${response.status}`);
193	  const bytes = Buffer.from(await response.arrayBuffer());
194	  fs.writeFileSync(outputPath, bytes);
195	  return bytes.length;
196	}
197	
198	function promptFor(item: StoryboardFile["items"][number]) {
199	  return [
200	    `Create a 16:9 Chinese product promo image for the video titled "${item.title}".`,
201	    "Subject: Doubao premium plan membership purchase recommendation.",
202	    `Narration idea: ${item.narration_cn}`,
203	    "Visual direction: restrained premium product visual with a clean high-contrast composition, readable Chinese headline/key elements, and solid panels behind any text.",
204	    "Subtitle safe area: keep critical text and key objects out of the lower 24% of the frame.",
205	    "Avoid tiny text, glassmorphism, blurred text backgrounds, and heavy glow; do not show real logos, real people, fake app screenshots, or unverifiable prices/plan rights."
206	  ].join(" ");
207	}
208	
209	async function main() {
210	  const loadedEnvFiles = envCandidates.filter((candidate) => loadEnvFile(candidate));
211	  const imageDir = path.join(outputDir, "real-provider-images");
212	  const manifestPath = path.join(process.cwd(), videoRunFiles.realProviderManifest);
213	  fs.mkdirSync(imageDir, { recursive: true });
214	
215	  const storyboard = readJson<StoryboardFile>(videoRunFiles.storyboard);
216	  const existingImages = storyboard.items
217	    .map((item) => path.join(imageDir, `${String(item.order).padStart(2, "0")}.png`))
218	    .filter((filePath) => fs.existsSync(filePath));
219	  if (existingImages.length === storyboard.items.length && fs.existsSync(manifestPath)) {
220	    console.log("real-media:smoke skipped");
221	    console.log("reason=completed_image_manifest_exists");
222	    return;
223	  }
224	
225	  const baseUrl = requiredEnv("APIMART_BASE_URL");
226	  const apiKey = requiredEnv("APIMART_API_KEY");
227	  const model = process.env.REAL_IMAGE_MODEL ?? "gemini-3-pro-image-preview";
228	  const imageApiPath = process.env.IMAGE_API_PATH ?? "/v1/images/generations";
229	  const rawStatusPath = process.env.TASK_STATUS_API_PATH ?? "/v1/tasks";
230	  const statusBasePath = rawStatusPath.endsWith("/") ? rawStatusPath.slice(0, -1) : rawStatusPath;
231	  const pollRounds = numberFromEnv("REAL_IMAGE_MAX_POLL_ROUNDS", 30, 30);
232	  const submitRetries = numberFromEnv("REAL_IMAGE_MAX_SUBMIT_RETRIES", 3, 30);
233	  const pollIntervalMs = numberFromEnv("REAL_IMAGE_POLL_INTERVAL_MS", 10000, 60000);
234	
235	  if (baseUrl === "mock") throw new Error("APIMART_BASE_URL points to mock mode");
236	
237	  const submitUrl = new URL(imageApiPath, baseUrl).toString();
238	  const attempts: Array<Record<string, unknown>> = [];
239	  const tasks = new Map<number, { task_id: string; status: TaskStatus; result_url: string | null; output_path: string }>();
240	
241	  for (const item of storyboard.items) {
242	    const outputPath = path.join(imageDir, `${String(item.order).padStart(2, "0")}.png`);
243	    if (fs.existsSync(outputPath)) {
244	      tasks.set(item.order, { task_id: "existing", status: "completed", result_url: null, output_path: outputPath });
245	      attempts.push({ phase: "reuse", order: item.order, ok: true, path: toProjectPath(outputPath) });
246	      continue;
