22	function formatSrtTime(seconds: number) {
23	  const totalMs = Math.max(0, Math.round(seconds * 1000));
24	  const hours = Math.floor(totalMs / 3_600_000);
25	  const minutes = Math.floor((totalMs % 3_600_000) / 60_000);
26	  const secs = Math.floor((totalMs % 60_000) / 1000);
27	  const ms = totalMs % 1000;
28	  return `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}:${String(secs).padStart(2, "0")},${String(ms).padStart(3, "0")}`;
29	}
30	
31	function textLength(value: string) {
32	  return Array.from(value.replace(/\s+/g, "")).length || 1;
33	}
34	
35	function splitLongChunk(value: string, maxChars: number) {
36	  const chunks: string[] = [];
37	  let remaining = value.trim();
38	  while (Array.from(remaining).length > maxChars) {
39	    const chars = Array.from(remaining);
40	    const preferred = chars
41	      .slice(0, maxChars + 1)
42	      .map((char, index) => ({ char, index }))
43	      .reverse()
44	      .find((entry) => entry.index >= Math.floor(maxChars * 0.35) && /[，,；;、\s]/.test(entry.char));
45	    const cutAt = preferred ? preferred.index + 1 : maxChars;
46	    const chunk = chars.slice(0, cutAt).join("").trim();
47	    if (chunk) chunks.push(chunk);
48	    remaining = chars.slice(cutAt).join("").trim();
49	  }
50	  if (remaining) chunks.push(remaining);
51	  return chunks;
52	}
53	
54	function splitNarration(text: string) {
55	  const normalized = text.replace(/\s+/g, " ").trim();
56	  const sentenceChunks = normalized.match(/[^。！？!?；;]+[。！？!?；;]?/g)?.map((item) => item.trim()).filter(Boolean) ?? [normalized];
57	  const chunks = sentenceChunks.flatMap((chunk) => splitLongChunk(chunk, 26)).filter(Boolean);
58	  return chunks.length > 0 ? chunks : [normalized];
59	}
60	
61	function wrapSubtitleText(text: string) {
62	  const chars = Array.from(text);
63	  if (chars.length <= 26) return text;
64	  const preferred = chars
65	    .slice(0, 27)
66	    .map((char, index) => ({ char, index }))
67	    .reverse()
68	    .find((entry) => entry.index >= 10 && /[，,；;、\s]/.test(entry.char));
69	  const cutAt = preferred ? preferred.index + 1 : Math.ceil(chars.length / 2);
70	  return `${chars.slice(0, cutAt).join("").trim()}\n${chars.slice(cutAt).join("").trim()}`;
71	}
72	
73	interface SubtitleCue {
74	  index: number;
75	  order: number;
76	  start_seconds: number;
77	  end_seconds: number;
78	  text: string;
79	  image_path?: string;
80	}
81	
82	function buildSubtitleCues(items: StoryboardItem[]) {
83	  const cues: SubtitleCue[] = [];
84	  let cueIndex = 1;
85	
86	  for (const item of items) {
87	    const segmentStart = item.timeline_start_seconds ?? 0;
88	    const segmentDuration = item.audio_duration_seconds ?? item.duration_seconds;
89	    const chunks = splitNarration(item.narration_cn);
90	    const weights = chunks.map(textLength);
91	    const totalWeight = weights.reduce((total, value) => total + value, 0) || chunks.length;
92	    let localCursor = 0;
93	
94	    chunks.forEach((chunk, chunkIndex) => {
95	      const isLast = chunkIndex === chunks.length - 1;
96	      const duration = isLast ? segmentDuration - localCursor : segmentDuration * (weights[chunkIndex] / totalWeight);
97	      const start = segmentStart + localCursor;
98	      const end = segmentStart + Math.min(segmentDuration, localCursor + duration);
99	      if (end > start) {
100	        cues.push({
101	          index: cueIndex,
102	          order: item.order,
103	          start_seconds: Number(start.toFixed(3)),
104	          end_seconds: Number(end.toFixed(3)),
105	          text: chunk
106	        });
107	        cueIndex += 1;
108	      }
109	      localCursor += duration;
110	    });
111	  }
112	
113	  return cues;
114	}
115	
116	function writeSrt(filePath: string, cues: SubtitleCue[]) {
117	  const lines = cues.flatMap((cue) => [
118	    String(cue.index),
119	    `${formatSrtTime(cue.start_seconds)} --> ${formatSrtTime(cue.end_seconds)}`,
120	    wrapSubtitleText(cue.text),
121	    ""
122	  ]);
123	  fs.writeFileSync(filePath, `${lines.join("\n").trimEnd()}\n`, "utf8");
124	}
125	
126	function findSubtitleFont() {
127	  try {
128	    const fonts = execFileSync("magick", ["-list", "font"], { encoding: "utf8" });
129	    const fontNames = ["PingFang-SC-Semibold", "Hiragino-Sans-GB-W6", "Heiti-SC-Medium"];
130	    const fontName = fontNames.find((candidate) => fonts.includes(`Font: ${candidate}`));
131	    if (fontName) return fontName;
132	  } catch {
133	    // Fall back to system font files below.
134	  }
135	  const candidates = [
136	    "/System/Library/Fonts/Hiragino Sans GB.ttc",
137	    "/System/Library/Fonts/STHeiti Medium.ttc",
138	    "/System/Library/Fonts/STHeiti Light.ttc",
139	    "/System/Library/Fonts/Supplemental/Arial Unicode.ttf"
140	  ];
141	  return candidates.find((candidate) => fs.existsSync(candidate));
142	}
143	
144	function renderSubtitleImages(cues: SubtitleCue[], fontPath: string | undefined) {
145	  const imageDir = path.join(composeDir, "subtitle-images");
146	  fs.rmSync(imageDir, { recursive: true, force: true });
147	  fs.mkdirSync(imageDir, { recursive: true });
148	  const panelWidth = 1240;
149	  const panelHeight = 132;
150	  const textWidth = 1176;
151	  const textHeight = 108;
152	
153	  return cues.map((cue) => {
154	    const imagePath = path.join(imageDir, `${String(cue.index).padStart(3, "0")}.png`);
155	    const textLayerPath = path.join(imageDir, `${String(cue.index).padStart(3, "0")}.text.png`);
156	    const args = [
157	      "-size",
158	      `${panelWidth}x${panelHeight}`,
159	      "xc:none",
160	      "-fill",
161	      "rgba(0,0,0,0.16)",
162	      "-draw",
163	      `roundrectangle 5,8 ${panelWidth - 6},${panelHeight - 1} 22,22`,
164	      "-fill",
165	      "rgba(36,50,74,0.72)",
166	      "-draw",
167	      `roundrectangle 0,0 ${panelWidth - 1},${panelHeight - 8} 20,20`,
168	      "-stroke",
